INSERT INTO `appelation` (`id`, `appelation_id`, `label`, `description`, `titre`, `discr`) VALUES (1,NULL,'Royaume','Le Roi décide !','Roi','extended'),(2,1,'Région','Regroupant plusieurs fiefs, la région est sous la responsabilité d\'un gouverneur, souvent une personne issue de la noblesse locale.','Gouverneur','extended'),(3,2,'Fief','Un fief produit des ressources que gère son Seigneur.','Seigneur','extended'),(4,NULL,'Royaume mageocratie','Le Royaume regroupe les terres attachées aux tours de magie !','Reine','extended'),(5,4,'Fief','Un fief, nommé Tour, produit des ressources et est sous la responsabilité d\'un Seigneur.','Seigneur','extended'),(6,NULL,'Territoires indépendants','Ses habitants sont de la même race mais n\'ont de cohésion souvent que face Ã  l\'ennemi extérieur.','Chef de guerre','extended'),(7,6,'Tribu','Une tribu défend farouchement son territoire !','Chef','extended'),(8,NULL,'Royaume avec Conseil des sages','Un Royaume dont le roi est assisté par les sages.','Roi','extended'),(9,8,'Région','De grands territoires glacés.','Chef de guerre','extended'),(10,NULL,'Ensemble de petits Royaumes','Les Royaumes sont relativement indépendants les uns envers les autres.','Roi','extended'),(11,10,'Royaume','Un territoire qui serait appelé fief ailleurs.','Roi','extended'),(12,NULL,'Anarchie','Il n\'y a pas de cohésion de pays, bien que la guerre tende Ã  aider Ã  la prédominance d\'un chef unique.','Aucun','extended'),(13,12,'Fief','Des terres réunies par la force des armes et de la violence.','Chef ou Roi','extended'),(14,NULL,'Compagnie Apatride','Certains groupes, souvent mercenaires ou pirates, vivent en dehors de toute affiliation Ã  un pays.\r\nrares sont ceux qui durent longtemps, mais certains y parviennent et prospèrent même hors de tout cadre légal.','Chef','extended'),(15,NULL,'Empire','Système politique qui se veut centralisé et manifeste dans son appellation sa volonté expansionniste.','Empire','extended'),(16,NULL,'Théocratie','Société où l\'autorité politique a une assise d\'ordre divin et où le détenteur du pouvoir est soit l\'incarnation d\'un dieu, soit son descendant, soit encore son ministre. Dans un état théocratique pur, la loi civile et la loi religieuse se confondent.',NULL,'extended'),(17,16,'Province','Division administrative d\'un territoire où des représentants du pouvoir central ont la délégation d\'y exercer le pouvoir exécutif civil ou militaire','Gouverneur','extended'),(18,1,'Cité Etats','Une cité-état est un espace géographique contrôlé exclusivement par une ville.','CitÃ© Etats','extended'),(19,NULL,'Royaume','Le Roi décide !','Roi','extended'),(20,19,'Fief','Un fief produit des ressources que gère son Seigneur.','Seigneur','extended'),(21,NULL,'Clans indépendants','Chaque clan a un chef qui préserve jalousement son indépendance. Il arrive que les clans s\'unissent contre une menace extérieure, mais ces alliances ne durent pas.','Amenokal','extended'),(22,NULL,'Clans nomades','Chaque clan préserve son indépendance mais reconnaît l\'autorité d\'un Clan référence.','Shah','extended'),(23,NULL,'Territoire','Le Sultan règne en maître.','Sultanat','extended'),(24,NULL,'Sultanat','Le Sultan règne ici en maître.','Territoire','extended'),(25,24,'Satrapie','Les Satrapes sont les gouverneurs du Sultan. Ils gèrent en son nom une vaste zone géographique.','RÃ©gion','extended'),(26,NULL,'République impériale',NULL,NULL,'extended'),(27,NULL,'Terres inconnues','Ce territoire ne peut pas être conquis !\nC\'est un lieux de mystères et d\'exploration',NULL,'extended'),(28,28,'Océan','Ce territoire ne peut pas être conquit\r\n\r\nIl renferme nombre de mystères qu\'il sera bien difficile voir impossible d\'explorer',NULL,'extended');
