INSERT INTO `competence_family` (`id`, `label`, `description`, `discr`) VALUES (1,'Agilité','La vivacité et l\'adresse peuvent compenser un éventuel défaut de force !','extended'),(2,'Herboristerie','Fournir des ingrédients et savoir les utiliser peut se révéler crucial !','extended'),(3,'Prêtrise','Le mystère lié aux dieux !','extended'),(4,'Alchimie','La connaissance de recettes permet de réaliser des Potions aux effets remarquables !','extended'),(5,'Cartographie','Bien se préparer et obtenir des informations rares est précieux !','extended'),(6,'Protection','Avoir une armure c\'est bien mais parfois insuffisant !','extended'),(7,'Armes à 1 main','Utiliser des armes à une main plus conséquentes qu\'une simple dague !','extended'),(8,'Commerce','Les marchandises peuvent apporter des avantages déterminants !','extended'),(9,'Résistance','Savoir garder un secret ou se prémunir de certaines agressions !','extended'),(10,'Armes à 2 mains','Utiliser de grandes armes à deux mains avec puissance !','extended'),(11,'Discrétion','Pour vivre heureux, vivons cachés !','extended'),(12,'Richesse','L\'argent est une arme également !','extended'),(13,'Armes à distance','<p>Pour ceux qui préfèrent les combats de loin...</p>','extended'),(14,'Espionnage','En savoir plus sur les autres en toute discrétion !','extended'),(15,'Ritualisme','Tout est possible avec un rituel, mais c\'est dangereux !','extended'),(16,'Armes d\'hast','<p>Utiliser les lances et autres armes très longues de ce type !</p>','extended'),(17,'Guérison','Le meilleur ami que l\'on aime avoir à proximité !','extended'),(18,'Sauvagerie','Quand on mise sur l\'attaque, autant s\'en donner les moyens !','extended'),(19,'Armure','Porter de quoi se protéger, est plus qu\'utile pour les combats !','extended'),(20,'Littérature','La connaissance apporte bien des avantages !','extended'),(21,'Charisme','<p>La force brute n\'est pas le seul moyen de parvenir à ses fins !</p>','extended'),(22,'Forge','<p>Le travail du métal et du cuir c\'est la santé !</p>','extended'),(23,'Magie','Les sorciers sont craints, à juste titre !','extended'),(24,'Stratégie','Un bon chef apporte des atouts indéniables à ceux qui le suivent !','extended'),(25,'Artisanat','<p>Rien de mieux qu\'un bon Artisan pour développer un fief !</p>','extended'),(26,'Noblesse','Un titre permet parfois de mieux protéger qu\'une armure !','extended'),(27,'Survie','Il y a des fois où la résistance du corps est le dernier recours !','extended'),(28,'Arts','L\'art adoucit les moeurs !','extended'),(29,'Observation','Deux yeux bien exercés sont un atout indéniable !','extended'),(30,'Torture','C\'est quand même le moyen le plus simple pour obtenir des informations !','extended'),(31,'Attaque sournoise','Pourquoi attaquer de face quand on peut le faire de dos ?','extended'),(32,'Politique','Très utile pour les discussions diplomatiques, cette compétence inclut aussi le beau parler !','extended'),(33,'Vol','Autant récupérer discrètement un objet que de dépouiller des cadavres !','extended');
