INSERT INTO `domaine` (`id`, `label`, `description`, `discr`) VALUES (1,'Invocations','<p>Le Mage se sp&eacute;cialise dans l\'invocation de cr&eacute;atures, esprits ou armes &eacute;th&eacute;r&eacute;es.&nbsp;</p>','extended'),(2,'Malédictions','<p>Le Mage se sp&eacute;cialise dans le contr&ocirc;le et les actions sur les autres. &nbsp;</p>','extended'),(3,'Illusions','<p>Le Mage se sp&eacute;cialise dans la tromperie et la dissimulation.</p>','extended'),(4,'Divination','<p>Le Mage se sp&eacute;cialise dans l\'obtention d\'avantages et de d&eacute;placements.</p>','extended'),(5,'Nécromancie','<p>Le Mage se sp&eacute;cialise dans le mal qu\'il peut faire aux autres.</p>','extended');
