INSERT INTO `rangement` (`id`, `localisation_id`, `label`, `precision`, `discr`) VALUES (1,3,'1003Objets de jeu Hors stock',NULL,'extended'),(2,1,'Caisse BI','Caisse contenant narguilés, pipes et statues/tablettes incas','extended'),(3,1,'Caisse BJ','Caisse contenant des paniers en osier (non exhaustif), des carafes et des gourdes','extended'),(4,1,'Caisse BD','Caisse contenant les ustensiles et ingrédients d\'alchimie','extended'),(5,1,'Caisse AH','Caisse 2/3 contenant les armures','extended'),(6,1,'Caisse AK','Rangement à  tiroirs contenant les bijoux.\r\n- Tiroir du haut: bagues et broches\r\n- Tiroir 2: Bracelets et minis ustensiles stylisés\r\n- Tiroir 3: Boucles d\'oreilles et accessoires de coiffure\r\n- Autres tiroirs: colliers\r\n- Tiroir du bas: objets à  trier','extended'),(7,1,'Caisse CD','Caisse contenant les plantes et les minéraux (exceptés les pierres précieuses)','extended'),(8,1,'Caisse BG','Caisse 1/2 contenant les éclairages','extended'),(9,1,'Caisse CG','Caisse de décorations mixte','extended'),(10,1,'Caisse CF','Caisse contenant les statuettes, effigies et les armes d\'apparat','extended'),(11,1,'Caisse BE','Caisse concernant les parchemins et carnets, les instruments de musique, les coffres et serrures et les casses-têtes','extended'),(12,1,'Caisse AB','Caisse contenant les casques','extended'),(13,1,'Caisse AG','Caisse 1/3 contenant les armures','extended'),(14,1,'Caisse AC','Caisse contenant les perruques, les chapeaux et les accessoires de costume','extended'),(15,1,'Caisse CH','Coffre contenant les pierres précieuses, ainsi que les pièces','extended'),(17,1,'Caisse AA','Caisse contenant les masques, le maquillage et les accessoires de grimage (fausses oreilles, cornes etc.)','extended'),(18,1,'Caisse AJ','Caisse 3/3 contenant les armures','extended'),(19,1,'Caisse AI','Caisse contenant les ceintures, les fourreaux et les bourses','extended'),(20,1,'Caisse AL','Caisse contenant les chaussures accessoires allant avec','extended'),(21,1,'Caisse BA','Caisse 1/3 contenant les armes','extended'),(22,1,'Caisse BB','Caisse 2/3 contenant les armes','extended'),(23,1,'Caisse BC','Caisse 3/3 contenant les armes','extended'),(24,1,'Caisse BF','Caisse contenant la vaisselle décorative','extended'),(25,1,'Caisse BH','Caisse 2/2 contenant les éclairages','extended'),(26,1,'Caisse BK','Caisse 1/2 contenant les boucliers','extended'),(27,1,'Caisse BL','Sac 2/2 contenant les boucliers','extended'),(28,1,'Caisse CA','Caisse contenant les poupées (entières)','extended'),(29,1,'Caisse CC','Caisse contenant les faux-animaux, et leurs attributs (plumes, cornes etc) exceptés les ingrédients','extended'),(30,1,'Caisse CE','Caisse contenant les ossements','extended'),(31,1,'A réparer',NULL,'extended'),(34,4,'A DEFINIR ','Il faut un rangement pour chaque objet sinon larp plante','extended'),(36,1,'Container 1, Hors caisse',NULL,'extended'),(37,4,'A créer /à  acheter',NULL,'extended');
