INSERT INTO `religion_level` (`id`, `label`, `index`, `description`, `discr`) VALUES (1,'Fanatique',3,'Un Fanatique ne peut avoir qu\'une seule religion !\r\nToutes les autres sont considérées comme hérétiques.\r\nIl est plus efficace lorsqu\'il s\'agit de participer à  une Prière  de son dieu, comptant comme 8 participants (mais il refusera catégoriquement de participer à  une Prière dédiée à  un autre dieu que le sien).','extended'),(2,'Fervent',2,'Un fervent ne peut l\'être que dans une seule religion !\r\nIl peut être Pratiquant dans autant d\'autres religions qu\'il le souhaite.\r\nIl est plus efficace lorsqu\'il s\'agit de participer à  une Prière  de son dieu principal, comptant comme 4 participants (mais il comptera moins dans une Prière dédiée à  un autre dieu que celui-ci).','extended'),(3,'Pratiquant',1,'Un Pratiquant peut l\'être dans autant de religions qu\'il le souhaite !\r\nIl est plus efficace lorsqu\'il s\'agit de participer à  une Prière  de l\'un des dieux qu\'il vénère, comptant comme 2 participants.','extended');
/*!40000 ALTER TABLE `religion_level` ENABLE KEYS */;
