INSERT INTO `rule` (`id`, `label`, `url`, `description`, `discr`) VALUES (87,'LH6 - Statut des participants','status-participan-68225bafadceb7-09593959.pdf','<p>Un résumé des différentes types de participations possible au LH6</p>','extended'),(93,'LH7 - Feuille d\'arène','LH7-Feuille-d-are-685c30b2055941-89762646.pdf','<p>Voici la feuille d’arène à remplir en amont et remettre au Responsable d’arène pour chaque combat d’arène auquel votre groupe participera.</p>\r\n<p>Pensez à prendre votre fiche de fief en cas de conquête.</p>\r\n<p>Elle représente votre plan de bataille, l\'acheminement de vos troupes, votre préparation et se doit d\'être définitive au moment de sa remise avant le combat.</p>','extended'),(102,'LH7 - Magna Carta','magna-lh7-685c3230170b00-18409931.pdf','<p>La carte du monde pour LH7</p>','extended'),(110,'LH7 - Who\'s Who ou Personnages Illustres - v3','whoswho-7-2025-07.pdf','<p>Les personnages ayant suffisamment de renommée pour que vous connaissiez leur existence</p>','extended'),(111,'LH7 - Lettre d\'intention','Lettre d\'intention LH7.pdf','<p>A lire avant votre inscription ou apr&egrave;s si vous ne l\'aviez pas fait avant !</p>','extended'),(112,'LH7 - Conditions d\'inscription','Les conditions d\'inscription LH7.pdf','<p>Vous les signez lors de votre inscription &agrave; LH7 et du coup, vous vous engagez &agrave; les respecter.</p>','extended'),(113,'LH7 - Les règles du jeu (2025-05-31 - 30Mo)','LH7_Regles_20250531.pdf',NULL,'extended'),(115,'LH7 - Carte frontières d\'Hyborée','carte-frontieres--685c32eaa2b187-06884944.pdf','<p>La carte du monde et des frontières connues d\'Hyborée pour le LH7 </p>','extended'),(116,'LH7 - Livret de Sécurité','LH7-secu-emotionn-6862eb6438ce11-81561684.pdf','<p>Règles de sécurité : physique, combat, émotionelle et du site. </p>','extended'),(117,'LH7-Consignes générales','LH7_Consignes générales.pdf',NULL,'extended');
