&agrave; du grand mur sur la province khitane de Guanga&iuml;n.</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'extended','{\"type\":\"Feature\",\"properties\":{},\"geometry\":{\"type\":\"Polygon\",\"coordinates\":[[[180.921875,-65.796875],[181.03125,-65.96875],[181.15625,-66.1875],[181.3125,-66.453125],[181.40625,-66.625],[181.578125,-66.9375],[181.796875,-67.25],[181.9375,-67.484375],[182.125,-67.8125],[182.28125,-68.078125],[182.34375,-68.3125],[182.53125,-68.5625],[182.75,-68.859375],[182.921875,-69.09375],[183.0625,-69.28125],[183.21875,-69.5],[183.375,-69.734375],[183.453125,-69.921875],[183.484375,-70.125],[183.46875,-70.34375],[183.328125,-70.5625],[183.203125,-70.796875],[183.03125,-71.09375],[182.953125,-71.328125],[182.828125,-71.546875],[182.71875,-71.859375],[182.671875,-72.109375],[182.609375,-72.390625],[182.59375,-72.59375],[182.515625,-72.890625],[182.390625,-73.21875],[182.296875,-73.453125],[182.328125,-73.71875],[182.421875,-73.9375],[182.5,-74.203125],[182.59375,-74.453125],[182.6875,-74.796875],[182.703125,-75.140625],[182.65625,-75.46875],[182.546875,-75.890625],[182.421875,-76.359375],[182.28125,-76.609375],[182.203125,-76.96875],[182.234375,-77.34375],[182.25,-77.5625],[182.25,-77.890625],[182.109375,-78.265625],[182.078125,-78.6875],[182.03125,-79],[182,-79.421875],[181.96875,-79.796875],[181.875,-80.03125],[181.859375,-80.375],[181.859375,-80.703125],[181.953125,-81.078125],[182.046875,-81.46875],[182.109375,-81.75],[182.25,-82.109375],[182.40625,-82.296875],[182.671875,-82.65625],[182.875,-82.859375],[182.96875,-83.046875],[182.90625,-83.296875],[182.890625,-83.578125],[182.875,-83.890625],[182.875,-84.1875],[182.890625,-84.453125],[183.125,-84.671875],[183.375,-84.875],[183.625,-85.078125],[183.9375,-85.34375],[184.03125,-85.609375],[184.125,-85.90625],[184.265625,-86.1875],[184.375,-86.546875],[184.40625,-86.953125],[184.421875,-87.21875],[184.703125,-87.59375],[184.90625,-87.828125],[185.296875,-88.046875],[185.6