,3,NULL),(434,83,NULL,5,14,21,'Nom_434','<p>Ces îles autrefois indépendantes ont été conquises par le Ghulistan qui s\'y est implanté avec l\'intention de peser sur la navigation dans la mer de la Vilayet. Le comptoir commercial n\'a pas résisté au pillage qui s\'en est suivi.</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'extended','{\"type\":\"Feature\",\"properties\":{},\"geometry\":{\"type\":\"Polygon\",\"coordinates\":[[[140,-72.875],[138.375,-74],[137.875,-78.125],[140.75,-80],[142.25,-77.875],[141.375,-73.5],[140,-72.875]]]}}','#89f4e6',230,10,2,NULL,NULL,'stable',NULL,3,NULL),(435,NULL,NULL,27,NULL,NULL,'Nom_435','<p>Iles peu fr&eacute;quent&eacute;es et difficiles d\'acc&egrave;s</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'extended',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL),(436,NULL,NULL,27,NULL,43,'Nom_436','<p>Iles peu fr&eacute;quent&eacute;es et difficiles d\'acc&egrave;s</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'extended',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL),(437,NULL,NULL,27,NULL,NULL,'Nom_437','<p>Iles peu fr&eacute;quent&eacute;es et difficiles d\'acc&egrave;s</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'extended',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,NULL),(438,NULL,NULL,27,1,NULL,'Nom_438','<p>Iles peu fr&eacute;quent&eacute;es et difficiles d\'acc&egrave;s</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'extended','{\"type\":\"Feature\",\"properties\":{},\"geometry\":{\"type\":\"Polygon\",\"coordinates\":[[[161.625,-134.71875],[162.90625,-136],[162.125,-138.78125],[159.90625,-140.46875],[156.59375,-140.0625],[155.75,-135.78125],[157.1875,-132.46875],[159.3125,-131.21875],[160.84375,-132],[161.625,-134.71875]]]}}','#5677fc',NULL,NULL,NULL,NULL,NULL,NULL,1,3,NULL),(439,50,NULL,6,11,35,'Nom_439','<p>Territoire d\'origine du Clan des Blaireaux Gris.</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL